import json,re
D=json.load(open('promesses-2027-data.json'))
import os
D['repo_url']=os.environ.get('REPO_URL','https://github.com/standujar-acc/Promesses-2027')
D['opendata']="Le projet est open source : le code est public sous licence MIT, et toutes les données de l'app (mesures, calculs, données d'entrée et sources) sont dans un fichier JSON ouvert, sous licence CC BY 4.0. Chacun peut refaire les calculs, les contester, proposer une correction ou les réutiliser."
D['about']="Promesses 2027 est un site indépendant : il n'a aucun lien avec un parti, un candidat ou une équipe de campagne, et ne reçoit aucun financement. Les mêmes règles s'appliquent à tous les candidats ; la méthode, le code et les données sont publics, et chaque correction est datée dans l'historique."
D['legal']="Éditeur : un particulier, à titre non professionnel ; contact par le bouton « Signaler une erreur » ou les tickets publics GitHub (voir ci-dessus). Hébergeur : Cloudflare, Inc., 101 Townsend Street, San Francisco, CA 94107, États-Unis, tél. +1 888 993 5273. Code sous licence MIT, données sous licence CC BY 4.0."
D['contact']="Une erreur, une source manquante, une mesure oubliée ? Le bouton « Signaler une erreur » est en bas de chaque page et dans chaque fiche (en dépliant la mesure). Chaque signalement est relu avant toute correction ; une correction est appliquée de la même façon à tous les candidats et apparaît dans l'historique. Un signalement ne contient que ce que vous écrivez. Vous pouvez aussi ouvrir un ticket public :"
D['privacy']="Pas de compte, pas de publicité, pas de mesure d'audience. Vos réponses au quiz et les informations saisies dans le simulateur restent dans votre navigateur : elles ne sont ni enregistrées ni envoyées. Seul le dernier onglet consulté est gardé sur votre appareil. Un signalement d'erreur envoie uniquement ce que vous écrivez dans le formulaire, sans votre adresse IP ; les quotas anti-abus utilisent une empreinte de l'adresse IP, effacée sous 48 heures. Le site est hébergé par Cloudflare et ne fait appel à aucun autre service : les polices de caractères sont servies par le site lui-même."
from life import merge; D=merge(D)
# quiz : propositions « vie quotidienne » précises et reconfirmées (clé candidat.thème.n = n-ième proposition du thème),
# texte dans data/quiz_plain.json [texte, concrètement, texte publié], explications dans data/quiz_effets.json
from quizfx import quiz_fx
QP=json.load(open('data/quiz_plain.json')); QE={k:v for k,v in json.load(open('data/quiz_effets.json')).items() if not k.startswith('_')}
D['quiz_extra']=[]
for k,v in QP.items():
    if k.count('.')!=2: continue
    cid,th,n=k.split('.'); p=[x for x in D['life'][cid] if x['theme']==th][0]['proposals'][int(n)-1]
    assert p['text']==v[2] and p['verifiable'] and not p['old'], f"quiz_plain.json : {k} ne correspond plus à une proposition précise et reconfirmée"
    assert k in QE, f"quiz_effets.json : explications manquantes pour {k}"
    D['quiz_extra'].append({'c':cid,'id':th+'.'+n,'life':True,'theme':th,'title':v[0],'quiz_text':v[0],'quiz_concret':v[1],**quiz_fx(QE[k],k)})
assert {k for k in QE if k.count('.')==2}<={k for k in QP if k.count('.')==2}, "quiz_effets.json : proposition « vie quotidienne » sans texte"
KEYS={c['id']+'.'+m['id'] for c in D['candidates'] for m in c['measures']}|{cid+'.'+x['theme']+'.'+str(n) for cid,arr in D['life'].items() for x in arr for n in range(1,len(x['proposals'])+1)}
for k,v in QE.items():
    if isinstance(v,dict) and v.get('complement'):
        assert all(r in KEYS and r.split('.')[0]==k.split('.')[0] for r in v['complement_ref']), f"quiz_effets.json : {k}, complément hors du programme du même candidat"
n=sum(c['claude_total']['n'] for c in D['candidates']); tot=sum(len(c['measures']) for c in D['candidates'])
urls=set()
for c in D['candidates']:
    for m in c['measures']:
        for e in m['estimates']: urls.add(e['url'])
        for i in (m.get('claude') or {}).get('inputs',[]): urls.add(i['url'])
D['method']=[
 f"<b>Notre chiffrage.</b> {tot} mesures analysées, dont {n} chiffrées avec la même règle pour tous : effet sur le solde public en Md€ par an, en année pleine à l'horizon 2030, en euros de 2026. Quand plusieurs chiffrages publiés existent, on retient leur médiane ajustée aux paramètres de 2027 ; sinon, un calcul ascendant à partir de données publiques. Chaque calcul et chaque donnée d'entrée sont affichés dans la fiche.",
 "<b>Règles communes.</b> Une même mesure vaut le même montant chez tous les candidats : retour à 62 ans 11,8 Md€ en 2030 (rendement de la réforme 2023, moins la part déjà perdue par la suspension) ; salaires des enseignants 3,9 Md€ par tranche de +10 % (chiffrage de l'Institut Montaigne remis aux salaires de 2024) ; AME remplacée par une aide d'urgence +0,9 Md€ (même méthode, appliquée à la dépense réelle de 2025) ; un recul de l'âge de départ au-delà de 64 ans, au rythme prévu par la réforme de 2023, n'a pas d'effet avant 2032 : seule compte en 2030 la fin de la suspension de cette réforme (+1,8 Md€) ; taxe Zucman +5 Md€ ; poste public supprimé 61,6 k€, dont la moitié rendue aux agents, avec 70 % du plan réalisé en 2030 ; chaque mesure est comptée à son état prévu en 2030 (montée en charge comprise) ; un montant cumulé sur le quinquennat est converti en flux de 2030 (3,5/15 du cumul, soit 70 % du rythme final) ; la CVAE, déjà supprimée par la loi d'ici 2030, n'est comptée chez personne ; le SMIC de référence est celui de juin 2026. Une mesure se juge reconfirmée mesure par mesure, quel que soit le document d'origine. Quand un candidat publie un budget ligne à ligne (RN, LFI, Retailleau, Zemmour), toute ligne d'au moins 1 Md€ qu'aucune fiche ne couvre est ajoutée : une dépense ou une baisse d'impôt vaut la médiane des chiffrages indépendants, à défaut le chiffre du camp (signalé, fourchette de ±50 %), une enveloppe vaut son montant ; une recette ou une économie n'est comptée qu'avec un chiffrage indépendant ou un paramètre publié (taux, assiette), sinon elle est listée « non comptée ». La lutte contre la fraude est comptée avec les leviers chiffrés par le Conseil d'analyse économique qui correspondent au champ de chaque mesure, dans la limite du chiffre du camp. Une baisse d'impôt annoncée sans calendrier est comptée en entier en 2030 ; une suppression d'aide compte pour sa seule part publique (pas la part payée hors budget, comme les certificats d'économies d'énergie) ; des aides réservées selon la nationalité ou la durée de séjour sont chiffrées avec l'étude qui correspond à la condition de chaque candidat.",
 "<b>Ce qui n'est pas compté.</b> Les mesures non reconfirmées en 2026 (marquées « À confirmer ») et les mesures dont un paramètre clé n'est pas publié (ampleur, taux, plafond) : elles sont « non chiffrables », avec une fourchette indicative dans la fiche. Une mesure qui exige une révision est comptée « si elle passe », chez tous les candidats. Pas d'effets macroéconomiques de bouclage ; effets de comportement seulement quand ils sont documentés. Un chiffrage qu'un candidat reprend comme le sien (d'un institut, d'une association ou d'un parti) compte comme chiffre de son camp, quel que soit son auteur ; une économie qui repose sur une baisse de flux ou un comportement supposés par une seule note n'est pas comptée, sauf si une évaluation ou une donnée officielle les établit.",
 "<b>Fourchette probable.</b> Chaque mesure a une valeur basse et une valeur haute ; le total en tire une fourchette à 80 % par simulation (20 000 tirages, propres à chaque candidat).",
 "<b>Verdicts.</b> Faisable : par décret ou par la loi avec une majorité. Sous conditions : coût, majorité ou financement incertains. Très difficile : rendement surévalué ou accord extérieur nécessaire. Exige une révision : impossible en l'état du droit sans réviser la Constitution ou les traités ; la fiche indique le chemin et qui doit dire oui. Une même situation juridique reçoit le même verdict chez tous les candidats.",
 f"<b>Sources.</b> {len(urls)} sources distinctes pour les chiffrages des fiches, sans compter celles du quiz, des repères et du volet « Vie quotidienne ». L'année des chiffrages publiés est affichée ; « base 2022 » signale une estimation antérieure au programme 2027, « agrégateur » un site de synthèse à confirmer par une source primaire.",
 "<b>Résumés.</b> Même gabarit pour tous : ce que le candidat promet, notre chiffrage, le principal obstacle.",
 "<b>Vie quotidienne.</b> Pour huit thèmes (sécurité, santé, école, environnement, logement, libertés, économie, rayonnement), on liste 1 à 3 propositions publiées par candidat. Une proposition est « vérifiable » si elle donne un chiffre, une échéance ou un moyen juridique précis ; sinon c'est une « intention ». La même règle s'applique à tous ; une proposition de 2022 que le camp n'a pas reprise en 2026 est signalée « non reconfirmée ». L'étiquette d'efficacité dit ce que montrent les évaluations sur ce type de mesure (prouvée, mitigée, non démontrée, pas d'étude), jamais si l'objectif est bon. Les repères « où en est la France » sont les mêmes pour tous les candidats : pour chaque thème, 7 à 14 chiffres officiels (SSMSI, Insee, DREES, DEPP, Dares, COR, Ofpra, Ancols, Eurostat, OCDE, OTAN, RTE, SDES, Citepa, Banque de France, Cour des comptes, Sénat, etc. ; seul le classement de la liberté de la presse vient d'une ONG, RSF, et il est signalé comme tel), choisis parmi ceux que les bilans officiels mettent en avant, problèmes comme progrès, y compris les faits sensibles (violences sexuelles, part des étrangers parmi les mis en cause) avec leur définition exacte. Chacun donne le dernier chiffre publié, de préférence son évolution sur au moins cinq ans (jamais depuis une année choisie pour son creux ou son pic), et la précaution de lecture donnée par la source (par exemple : délinquance enregistrée, pas commise ; « mis en cause » n'est pas « condamné »). Quatre sont affichés, les autres se déplient. Une même étude est lue de la même façon pour tous les candidats qui proposent ce type de mesure ; le site de campagne d'un candidat n'est jamais utilisé comme source sur un autre.",
 "<b>Simulateur.</b> Il applique à votre situation tout paramètre annoncé et confirmé, qu'il soit compté ou non dans notre total (si un paramètre clé manque, une note le dit), à terme, sans les mesures de financement : retraite comparée au droit actuel après la suspension de la réforme 2023 ; SMIC 1 477,93 € net (juin 2026) ; barème 2026 de l'impôt sur le revenu avec décote, sur le net imposable, pour une personne seule (parent isolé si elle a des enfants) ; allocations familiales 2026 avant modulation. Les pertes sont comptées comme les gains : aides réservées selon la nationalité ou la durée de séjour (même calcul pour les quatre candidats qui en proposent, chacun avec sa condition, « si la révision de la Constitution passe », et pour un ressortissant de l'UE « si le droit de l'UE change »), gel des prestations, baisse des minima ; le logement compte aussi (APL réservées selon la nationalité, relevées de 10 % ou gelées, à partir du montant que vous indiquez ; les mesures sans paramètre publié, comme la déduction des intérêts d'emprunt ou les prêts à taux zéro, sont signalées en note) ; les jours de carence et la durée du chômage sont affichés à part, car ils ne jouent qu'en cas d'arrêt ou de chômage long. Le report de l'âge de la retraite est exprimé en années, avec la durée de cotisation pour le taux plein quand elle est publiée. Un avantage déjà acquis aujourd'hui n'est pas compté comme un gain (heures sup : impôt et cotisations du salarié déjà exonérés). Ce sont des ordres de grandeur.",
 "<b>Quiz.</b> 20 duels tirés au hasard entre deux candidats sur un même thème ; chaque candidat apparaît 5 fois et aucune paire ne se répète. Les duels portent sur les mesures des fiches (chiffrées ou non chiffrables) et sur les propositions précises et reconfirmées du volet « Vie quotidienne » (école, santé, logement) ; un candidat sans proposition de ce type sur un thème n'y apparaît pas. À l'accueil, on peut choisir les thèmes qui comptent pour soi : ils reviennent plus souvent et comptent double dans le résultat. Chaque proposition est reformulée en langage courant. Dessous, un constat : la réalité française que la proposition veut traiter, avec le chiffre officiel (le dernier chiffre officiel et son évolution en %, même forme pour toutes ; les problèmes réels sont dits clairement, sans cause ni jugement). Puis « Pour » et « Contre » donnent en une ligne le meilleur argument réel de ceux qui la défendent et de ceux qui la critiquent : un fait que la proposition ne dit pas d'elle-même (ce qui s'est passé quand elle a été appliquée, un ordre de grandeur), jamais la proposition redite autrement ; avec la force des preuves de chacun (solides, mitigées, faibles, pas d'étude). Sous le duel, des cas réels sourcés (en France d'abord) et l'état des études. Même méthode pour toutes les mesures, sans fausse symétrie : on n'invente ni argument ni exemple pour équilibrer, et un exemple n'est retenu que s'il est pertinent, observé et de source reconnue ; on montre où penchent les faits et le lecteur juge ; les mesures du même type ont les mêmes cas et les mêmes niveaux de preuve. Le « Contre » tient compte du reste du programme : si une autre mesure du même candidat répond à la critique, elle est signalée. Pas de nom de candidat, pas de coût de la mesure, pas de faisabilité juridique, pas de jugement. Le résultat montre d'abord le ou les candidats les plus proches et ce qu'impliquent les propositions retenues (faisabilité, déficit ; « Les deux » compte la moyenne des deux effets), puis une pastille par proposition vue. La proximité est la part des propositions d'un candidat que vous avez retenues (choisie ou « Les deux ») ; une proposition d'un thème que vous marquez compte deux fois. Les égalités ne sont jamais départagées : les ex æquo sont signalés et affichés dans un ordre tiré au hasard. Suivent la tendance par thème, ce qui colle et ce qui colle moins chez les plus proches, et le détail des duels.",
 "<b>Sondages et contexte.</b> Intentions de vote au 1er tour : moyenne de "+str(len(D['sondages']['instituts']))+" instituts ("+" ; ".join(f"{i['institut']} pour {i['pour']}, du {i['terrain'][:-5].replace('-',' au ',1)}" for i in D['sondages']['instituts'])+"), dernière vague de chacun dont le terrain s'est achevé dans les 15 jours précédant le "+D['sondages']['date']+" ; pour chaque institut, milieu de la fourchette des hypothèses où le candidat est testé, même poids pour chaque institut. L'ordre des candidats suit cette moyenne. Source : notices de la Commission des sondages ; sondages masqués la veille et le jour de chaque tour. PLF 2027, Insee, taux à 10 ans d'octobre 2026. Ménages : 30,9 millions (Insee). 1 point de PIB ≈ 30 Md€."]
D['changelog'].insert(0,{'date':'26/10/2026','text':"Revue complète : règles de calcul communes à tous les candidats, SMIC et CVAE corrigés, verdicts alignés, mesures non confirmées sorties des totaux, résumés réécrits sur un même gabarit. Nouvelle interface pensée pour le mobile. Nouvel onglet « Vie quotidienne » : propositions, test vérifiable/intention, efficacité selon les études et repères officiels."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Retrait de l'onglet « Demander » : plus de réponses générées par une IA, seules restent les fiches, le simulateur et le quiz."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Nouvelle rubrique « Vos données » : les réponses au quiz et au simulateur ne sont ni enregistrées ni envoyées. Lien vers le code source (open source) en bas de chaque page."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"« Rien n'est enregistré » affiché sur l'accueil et le quiz. Polices servies par le site : plus aucun appel à Google Fonts."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Revue des sources : 8 liens morts remplacés (même document à une nouvelle adresse, copie archivée signalée, ou source équivalente) ; sources primaires pour trois mesures (Le Pen, renouvelables ; Glucksmann, Ukraine ; Attal, heures sup et chômage), avec proposition et obstacle précisés ; chiffrage OFCE pour le point d'indice (Mélenchon) ; borne « retour à 62 ans » alignée sur la valeur commune (Attal) ; une note reformulée (Retailleau). Quiz : six propositions qui n'apparaissaient pas par erreur y entrent (Le Pen, Retailleau, Attal, Lisnard)."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Quiz : 20 duels au lieu de 16, chaque candidat apparaissant 5 fois ; sous chaque proposition, « + » et « − » donnent les arguments des deux côtés et les risques, fondés sur des études (228 sources vérifiées, consultables sous chaque duel) et rédigés thème par thème avec les mêmes études pour les mesures du même type ; une même proposition ne peut plus revenir dans une partie. Résultat réorganisé : d'abord les candidats les plus proches et ce qu'impliquent vos choix, puis une pastille par proposition (la proximité est la part de propositions retenues, ce qui est affiché est ce qui est compté), la tendance par thème (les thèmes qui comptent pour vous peuvent compter double), ce qui colle et ce qui colle moins chez les plus proches, et le détail des duels replié ; les égalités ne sont jamais départagées. Nouveaux duels sur l'école, la santé et le logement, à partir des propositions précises du volet « Vie quotidienne », avec leurs explications sourcées ; à l'accueil, on peut choisir les thèmes qui comptent pour soi. Sous chaque proposition : un constat chiffré de la réalité française visée, puis « Pour » et « Contre » en une ligne chacun, avec la force des preuves de chacun et, si le même programme répond à la critique, ce qu'il prévoit ; sous le duel, des cas réels sourcés, en France d'abord, sans symétrie forcée. Constats au dernier chiffre officiel, en %, même forme pour toutes les propositions. Quand on retient les deux propositions d'un duel, l'effet sur le déficit est leur moyenne. Chaque « Pour » et chaque « Contre » apporte un fait que la proposition ne dit pas d'elle-même (ce qui s'est passé quand elle a été appliquée, un ordre de grandeur) : 53 propositions dont une ligne redisait la mesure réécrites, des deux côtés, avec 6 sources ajoutées"})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Simulateur revu après audit indépendant : les pertes sont comptées comme les gains (aides réservées selon la nationalité ou la durée de séjour, même calcul pour les quatre candidats concernés ; gel des prestations ; plafond des aides) ; gains oubliés ajoutés (enseignants, TVA sur les courses, carburant à 1,70 €/l, baisse de CSG, jeunes parents, 1 000 € à la naissance) ; heures sup ramenées au gain réel ; allocations familiales prises en compte dans le RSA ; jours de carence et durée du chômage affichés à part ; barres à échelle fixe ; droit actuel sourcé sur service-public.gouv.fr. Le simulateur applique désormais tout paramètre publié et confirmé, compté ou non dans le total (allocations familiales +10 % de Mélenchon). Nouveau réglage « Logement » : statut (locataire, propriétaire avec ou sans crédit, hébergé) et APL perçues ; APL réservées selon la nationalité ou relevées de 10 % selon les programmes ; notes sur la déduction des intérêts d'emprunt, les prêts à taux zéro et l'encadrement des loyers. Après un second audit : plus de gain fictif sur les heures sup (Philippe, Retailleau : impôt et cotisations du salarié déjà exonérés, aucune baisse de CSG annoncée) ; hausse des allocations familiales reprise par le RSA comme les baisses sont compensées ; APL « réservées aux Français » chez Le Pen ; règle de retraite toujours affichée et durée de cotisation pour le taux plein (Le Pen 42 ans, Mélenchon 40, Philippe 45) ; jour de carence « d'ordre public » dans le privé (Retailleau) ; pension minimale au niveau du SMIC (Mélenchon, montant maximal) ; gel des APL (Attal) ; plafond des aides à 70 % du SMIC calculé avec les APL pour une personne seule, en note pour les familles (modulation non publiée) ; pour un ressortissant de l'UE, la réservation d'aides exige aussi de changer le droit de l'UE ; TVA à 5,5 % sur le gaz et le carburant conditionnée à la directive européenne après 2030 ; SMIC relevé aussi pour les agents publics payés au minimum ; mesures de 2022 non reconfirmées signalées (Zemmour) ; impôt calculé sur le net imposable, avec la demi-part de parent isolé quand il y a des enfants."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Chiffrages revus en appliquant les règles communes aux sources : allocation unique de Philippe (350 € par enfant, seuils et aides remplacées non publiés) passée en « non chiffrable », comme celle de Lisnard, et retirée du simulateur ; blocage des prix de Mélenchon à la médiane des chiffrages publiés (Institut Montaigne 24 Md€, Gouvernement 20 Md€, soit 22 Md€), les prix pétroliers d'octobre 2026 écartant l'hypothèse de prix en baisse ; TVA sur l'énergie de Le Pen à la médiane des chiffrages indépendants (Bercy, Institut Montaigne : 14,1 Md€), sans le chiffre du camp, comme pour les autres candidats ; fusion des minima de Retailleau : baisse de 30 % désormais sourcée, chiffrage inchangé, et comptée dans le simulateur. Fourchettes probables calculées séparément pour chaque candidat."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Programmes revus après un audit indépendant, chaque point vérifié à la source : 48 mesures publiées et absentes des fiches sont ajoutées, dont les lignes des budgets détaillés du RN (contre-budget 2027 : taxe sur les carburants, part fiscale dès le 2e enfant, moins de 30 ans, successions, donations, Dutreil, prisons, proches aidants, dentaire, impôt sur la fortune financière…), de LFI (note du 14/10 : planification écologique, cantine gratuite, universités, hôpitaux, violences, allocations et APL +10 %, assurance chômage, taxe sur les transactions financières, fraude), de Retailleau (15 Md€ de cotisations patronales, congé de naissance, fraude) et de Zemmour (plan de 140 Md€ repris le 17/09 : accise sur les carburants, AME, renouvelables, Anah) ; Glucksmann (enseignants désormais chiffrés, chèque énergie triplé), Philippe (500 € au premier emploi, réservistes et volontaires, 3 jours de carence, fonds climat net des fonds remplacés), Attal (un mois d'engagement civique ; enseignants au même rythme que les autres), Lisnard (tribune du 16/04 : successions en ligne directe, quotient familial, CSG déductible ; aides après 5 ans de séjour). Règle commune pour les budgets ligne à ligne : dépenses et baisses d'impôts comptées, recettes et économies seulement avec un chiffrage indépendant ou un paramètre publié. Totaux : Le Pen −66,8, Mélenchon −126,2, Glucksmann −44,7, Philippe +2,6, Retailleau −1,0, Attal +4,2, Lisnard −29,4, Zemmour +21,3 Md€."})
D['changelog'].insert(0,{'date':'28/10/2026','text':"Sources consolidées : sources ajoutées aux mesures revues la veille, montant annoncé par chaque camp affiché, lignes du contre-budget du RN recoupées par l'Institut de l'Entreprise, plan de Retailleau recoupé par l'iFRAP, copies d'agrégateur signalées. Exonération d'impôt des moins de 30 ans (Le Pen) : médiane des deux chiffrages de l'Institut Montaigne (2022 et 2024), −2,2 Md€ au lieu de −3,7."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Repères « Où en est la France » pour chaque thème, les mêmes pour tous les candidats : 7 à 14 chiffres officiels par thème (sécurité, dont viols et violences sexuelles, immigration, retraites, travail, social, fiscalité, dépense, Europe, santé, école avec PISA 2025, énergie, environnement, logement, libertés, institutions, économie, rayonnement), avec l'évolution sur au moins cinq ans et la précaution de lecture de la source ; quatre affichés, les autres dépliables. Constats du quiz mis au dernier chiffre officiel (sécurité, aide médicale d'État, électricité, médecin traitant, arrêts maladie, SMIC, pauvreté des jeunes, éloignements, solde avec l'Union européenne, logement). Thèmes logement, libertés, institutions, économie et rayonnement : les repères non officiels (fondation, fédération HLM, cabinet privé, médias) sont remplacés par des sources publiques."})
D['changelog'].insert(0,{'date':'27/10/2026','text':"Cohérence des chiffres revue par un audit indépendant : retraites de Philippe ramenées à 5,8 Md€ (1,8 + 4, même base que Lisnard et Zemmour), total de +2,8 à +2,6 Md€ ; passage à 60 ans de Mélenchon rendu reproductible (−32,0 au lieu de −32,2) ; classes dédoublées lues de la même façon chez les cinq candidats concernés ; peines planchers : étude IPP de 2024 dans la fiche ; même formule pour toutes les mesures non chiffrables ; textes de méthode corrigés ; le fichier METHODOLOGIE.md est désormais généré à partir de l'onglet Méthode."})
